    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd (remove trailing slash if present and not just '/')
    if len(cwd) > 1 and cwd[-1] == '/':
        return None

    # Start with cwd if path is relative, otherwise start with '/'
    if path and path[0] == '/':
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    # Move to parent directory
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                continue

            # Append the component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current path is a symlink
            if current in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[current]

                # Determine where to resume resolution
                if target and target[0] == '/':
                    # Absolute symlink target: start from root
                    current = '/'
                    remaining = target[1:]
                else:
                    # Relative symlink target: resolve relative to symlink's directory
                    if current == '/':
                        current = '/'
                    else:
                        current = current.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    remaining = target

                # Break inner loop to process remaining components
                break
        else:
            # All components processed without encountering a symlink
            break

        # If we broke out due to a symlink, continue the outer loop
        # to process the remaining components

    # Return the result without trailing slash (except for '/')
    if current == '/':
        return '/'

    return current

